import * as fs from 'fs';
import * as path from 'path';
import Handlebars from 'handlebars';
import * as ejs from 'ejs';

export type TemplateEngine = 'hbs' | 'ejs' | 'html';

export interface TemplateContext {
  [key: string]: unknown;
}

const TEMPLATE_EXTENSIONS = ['.hbs', '.ejs', '.html'];

export function detectEngine(filePath: string): TemplateEngine {
  const lower = filePath.toLowerCase();
  if (lower.endsWith('.ejs')) return 'ejs';
  if (lower.endsWith('.html')) return 'html';
  return 'hbs';
}

export function findTemplateFile(templatesDir: string, name: string): string | null {
  if (!templatesDir) return null;
  const base = path.isAbsolute(name) ? name : path.join(templatesDir, name);
  if (TEMPLATE_EXTENSIONS.some((ext) => base.toLowerCase().endsWith(ext))) {
    return fs.existsSync(base) && fs.statSync(base).isFile() ? base : null;
  }
  for (const ext of TEMPLATE_EXTENSIONS) {
    const candidate = `${base}${ext}`;
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
  }
  return null;
}

function registerPartials(env: typeof Handlebars, partialsDir: string): void {
  if (!fs.existsSync(partialsDir)) return;
  const walk = (dir: string): void => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (
        entry.isFile() &&
        TEMPLATE_EXTENSIONS.some((ext) => entry.name.toLowerCase().endsWith(ext))
      ) {
        const relative = path.relative(partialsDir, full).replace(/\\/g, '/');
        const name = relative.replace(/\.[^/.]+$/, '');
        env.registerPartial(name, fs.readFileSync(full, 'utf8'));
      }
    }
  };
  walk(partialsDir);
}

function renderWithEngine(
  filePath: string,
  source: string,
  context: TemplateContext,
  templatesDir: string
): string {
  const engine = detectEngine(filePath);
  if (engine === 'ejs') {
    return ejs.render(source, context, {
      filename: filePath,
      root: templatesDir,
      async: false,
    });
  }
  if (engine === 'html') {
    return source;
  }
  const env = Handlebars.create();
  registerPartials(env, path.join(templatesDir, 'partials'));
  return env.compile(source)(context);
}

export function renderNamedTemplate(
  templatesDir: string,
  name: string,
  context: TemplateContext
): { html: string; filePath: string } | null {
  const filePath = findTemplateFile(templatesDir, name);
  if (!filePath) return null;
  const source = fs.readFileSync(filePath, 'utf8');
  return { html: renderWithEngine(filePath, source, context, templatesDir), filePath };
}

export function renderLayoutTemplate(
  templatesDir: string,
  layoutName: string,
  body: string,
  context: TemplateContext
): string | null {
  if (!templatesDir) return null;
  const layoutsDir = path.join(templatesDir, 'layouts');
  const filePath = findTemplateFile(layoutsDir, layoutName);
  if (!filePath) return null;
  const source = fs.readFileSync(filePath, 'utf8');
  return renderWithEngine(filePath, source, { ...context, body }, templatesDir);
}

import * as fs from 'fs';
import type { Page } from './types';
import { renderNamedTemplate, renderLayoutTemplate } from './template-engine';

export interface SiteConfig {
  title: string;
  templatesDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
}

const DEFAULT_TEMPLATE_NAME = 'default';
const DEFAULT_LAYOUT_NAME = 'default';

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function pageTitle(page: Page): string {
  return page.data.title ?? page.slug;
}

function layout(title: string, body: string): string {
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(title)}</title>`,
    '</head>',
    '<body>',
    body,
    '</body>',
    '</html>',
  ].join('\n');
}

function pageContext(page: Page, config: SiteConfig): Record<string, unknown> {
  return {
    title: pageTitle(page),
    slug: page.slug,
    link: page.link,
    date: page.data.date,
    tags: page.data.tags,
    content: page.content,
    html: page.html,
    site: { title: config.title },
    ...page.data,
  };
}

function builtinPageBody(page: Page, config: SiteConfig): string {
  const title = pageTitle(page);
  const meta = page.data.date ? `<p class="date">${escapeHtml(page.data.date)}</p>` : '';
  const tags = page.data.tags && page.data.tags.length > 0
    ? `<p class="tags">${page.data.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ')}</p>`
    : '';
  return [
    '<header>',
    `<h1>${escapeHtml(title)}</h1>`,
    meta,
    tags,
    '</header>',
    '<main>',
    page.html,
    '</main>',
    `<footer>Generated by ${escapeHtml(config.title)}</footer>`,
  ].join('\n');
}

function hasTemplates(templatesDir: string | undefined): templatesDir is string {
  return typeof templatesDir === 'string' && templatesDir !== '' && fs.existsSync(templatesDir);
}

export function renderPage(page: Page, config: SiteConfig): string {
  const title = pageTitle(page);
  const context = pageContext(page, config);

  let body: string;
  if (hasTemplates(config.templatesDir)) {
    const templateName = page.template ?? config.defaultTemplate ?? DEFAULT_TEMPLATE_NAME;
    const rendered = renderNamedTemplate(config.templatesDir, templateName, context);
    body = rendered ? rendered.html : builtinPageBody(page, config);
  } else {
    body = builtinPageBody(page, config);
  }

  if (hasTemplates(config.templatesDir)) {
    const layoutName = page.layout ?? config.defaultLayout ?? DEFAULT_LAYOUT_NAME;
    const wrapped = renderLayoutTemplate(config.templatesDir, layoutName, body, context);
    if (wrapped !== null) return wrapped;
  }

  return layout(title, body);
}

export function renderIndex(pages: Page[], config: SiteConfig): string {
  const sorted = [...pages].sort((a, b) => {
    const dateA = a.data.date ? Date.parse(a.data.date) : Number.NEGATIVE_INFINITY;
    const dateB = b.data.date ? Date.parse(b.data.date) : Number.NEGATIVE_INFINITY;
    if (dateA !== dateB) return dateB - dateA;
    return pageTitle(a).localeCompare(pageTitle(b));
  });

  const items = sorted.map((page) => {
    const date = page.data.date ? `<time datetime="${escapeHtml(page.data.date)}">${escapeHtml(page.data.date)}</time> ` : '';
    const tags = page.data.tags && page.data.tags.length > 0
      ? ` <em>(${page.data.tags.map((tag) => escapeHtml(tag)).join(', ')})</em>`
      : '';
    return `<li><a href="${escapeHtml(page.link)}">${escapeHtml(pageTitle(page))}</a> ${date}${tags}</li>`;
  }).join('\n');

  const body = [
    '<header>',
    `<h1>${escapeHtml(config.title)}</h1>`,
    '</header>',
    '<main>',
    sorted.length > 0 ? `<ul>\n${items}\n</ul>` : '<p>No pages found.</p>',
    '</main>',
  ].join('\n');

  if (hasTemplates(config.templatesDir)) {
    const layoutName = config.defaultLayout ?? DEFAULT_LAYOUT_NAME;
    const context: Record<string, unknown> = {
      title: config.title,
      site: { title: config.title },
      pages: sorted.map((page) => ({
        title: pageTitle(page),
        slug: page.slug,
        link: page.link,
        date: page.data.date,
        tags: page.data.tags,
      })),
    };
    const wrapped = renderLayoutTemplate(config.templatesDir, layoutName, body, context);
    if (wrapped !== null) return wrapped;
  }

  return layout(config.title, body);
}

